'use strict';
const $=id=>document.getElementById(id), C=Tracker, KEY='toggle-task.v1';
let state, editing=null, undo=null, readOnly=false, manualMode=false;
try{const raw=localStorage.getItem(KEY);state=raw?JSON.parse(raw):C.seed();if(state.version!==1||!Array.isArray(state.sessions)||!Array.isArray(state.projects)||!Array.isArray(state.users))throw Error('Formato desconocido');}catch(e){state=C.seed();readOnly=true;setTimeout(()=>notify('No se pudieron leer los datos guardados. No se sobrescribirán. '+e.message),0);}
function notify(message,action){const n=$('notice');n.replaceChildren(document.createTextNode(message));if(action){const b=document.createElement('button');b.textContent='Deshacer';b.onclick=action;n.append(b);}n.classList.add('show');clearTimeout(notify.timer);notify.timer=setTimeout(()=>n.classList.remove('show'),9000);}
function mutate(fn){try{if(readOnly)throw Error('Guardado bloqueado para proteger los datos.');const disk=localStorage.getItem(KEY);if(disk&&JSON.parse(disk).revision!==state.revision)throw Error('Otra ventana ha cambiado los datos. Recarga para continuar.');const next=structuredClone(state);fn(next);next.revision++;localStorage.setItem(KEY,JSON.stringify(next));state=next;render();$('saveState').textContent='Guardado local';return true;}catch(e){$('saveState').textContent='No guardado';notify(e.message);return false;}}
function options(select,items,current){select.replaceChildren(...items.map(x=>{const o=document.createElement('option');o.value=x.id;o.textContent=x.name;return o;}));if(items.some(x=>x.id===current))select.value=current;}
function el(tag,text,cls){const e=document.createElement(tag);if(text!=null)e.textContent=text;if(cls)e.className=cls;return e;}
const projectName=id=>state.projects.find(p=>p.id===id)?.name||'Proyecto desconocido';
const userName=id=>state.users.find(p=>p.id===id)?.name||'Perfil desconocido';
function inPeriod(s,period){const now=new Date();const start=period==='today'?new Date(now.getFullYear(),now.getMonth(),now.getDate()).getTime():period==='week'?Date.now()-7*86400000:0;return s.end>start;}
function filtered(){const q=$('search').value.toLocaleLowerCase();return C.mine(state).filter(s=>inPeriod(s,$('period').value)&&(s.description+' '+projectName(s.projectId)).toLocaleLowerCase().includes(q)).sort((a,b)=>b.start-a.start);}
function action(text,callback){const b=el('button',text);b.onclick=callback;return b;}
function render(){const current=$('project').value;options($('project'),state.projects.filter(p=>!p.archived),state.active?.projectId||current);options($('user'),state.users,state.userId);$('user').disabled=!!state.active;
for(const id of ['project','description','workType','units'])$(id).disabled=!!state.active&&!manualMode;
if(state.active&&!manualMode){$('description').value=state.active.description;$('workType').value=state.active.workType;$('units').value=state.active.units;}
$('toggle').textContent=manualMode?'✓':state.active?'■':'▶';$('toggle').setAttribute('aria-label',manualMode?'Guardar sesión manual':state.active?'Parar temporizador':'Iniciar temporizador');$('toggle').classList.toggle('running',!!state.active);$('miniToggle').textContent=state.active?'Parar':'Iniciar';
$('activeHint').textContent=state.active?'En marcha · se recupera al reabrir':'Todo listo. Empieza cuando quieras.';$('miniDescription').textContent=state.active?.description||'Listo para empezar';
$('palette').value=state.palette||'lilac';$('theme').value=state.theme||'dark';document.body.dataset.palette=state.palette||'lilac';document.body.dataset.theme=state.theme||'dark';
renderSessions();renderProjects();renderReports();renderDay();tick();}
function tick(){const value=C.format(state.active?(Date.now()-state.active.start)/1000:0);for(const id of ['clock','menuClock','miniClock'])$(id).textContent=value;document.title=state.active?value+' · Task Track':'Task Track';}
function renderSessions(){
 const list=filtered();$('sessionCount').textContent=list.length+' sesiones';$('total').textContent=C.format(list.reduce((n,s)=>n+C.seconds(s),0));const target=$('sessions');target.replaceChildren();
 if(!list.length){target.append(el('p','No hay sesiones para este perfil. Inicia el temporizador o añade una sesión manual.','empty'));return;}
 const groups=new Map();
 for(const s of list){const key=localDate(s.start).slice(0,10);if(!groups.has(key))groups.set(key,[]);groups.get(key).push(s);}
 for(const [day,records] of groups){const group=el('section',null,'daygroup'),header=el('header'),date=new Date(day+'T12:00:00');
 const label=day===localDate(Date.now()).slice(0,10)?'Hoy':date.toLocaleDateString('es-ES',{weekday:'short',day:'numeric',month:'short'});
 header.append(el('strong',label),el('time',C.format(records.reduce((n,s)=>n+C.seconds(s),0))));group.append(header);
 for(const s of records){const row=el('article',null,'session'),detail=action('',()=>openEditor(s));detail.className='details';
 const p=state.projects.find(p=>p.id===s.projectId),line=el('p'),dot=el('span',null,'projectdot');dot.style.background=projectColor(s.projectId);line.append(dot,document.createTextNode(projectName(s.projectId)+' · '+(p?.client||'')));detail.append(el('span',s.description||'+ Añadir descripción'),line);detail.setAttribute('aria-label','Editar '+(s.description||'sesión'));
 const resume=action('▶',()=>{C.own(state,s);if(mutate(n=>C.start(n,{projectId:s.projectId,description:s.description,workType:s.workType,units:0})))notify('Nueva sesión iniciada.');});resume.className='resume';resume.setAttribute('aria-label','Continuar '+(s.description||'sesión'));row.append(detail,el('time',C.format(C.seconds(s))),resume);group.append(row);}target.append(group);}
}
function projectColor(id){const colors=['#21c6a3','#b78be0','#dda53e','#689cd3'];return colors[Math.max(0,state.projects.findIndex(p=>p.id===id))%colors.length];}
function renderProjects(){const target=$('projects');target.replaceChildren();for(const p of state.projects){const ss=C.mine(state).filter(s=>s.projectId===p.id),card=el('article',null,'projectcard'),header=el('header');header.append(el('h2',p.name),action(p.archived?'Reactivar':'Archivar',()=>mutate(n=>{if(n.active?.projectId===p.id)throw Error('Detén el temporizador antes de archivar.');n.projects.find(x=>x.id===p.id).archived=!p.archived;})));card.append(header,el('p',p.client+' · '+(p.archived?'Archivado':'Activo')));
const metrics=el('div',null,'metrics');for(const [label,value] of [['Tiempo total',C.format(p.historicalMinutes*60+ss.reduce((a,s)=>a+C.seconds(s),0))],['Sesiones',ss.length],['Participantes',new Set(ss.map(s=>s.userId)).size]]){const v=el('div',label);v.append(el('b',value));metrics.append(v);}card.append(metrics,el('p',C.types.map(t=>t+': '+ss.filter(s=>s.workType===t).reduce((n,s)=>n+s.units,0)+' u.').join(' · ')));if(ss.length)card.append(el('p','Primera sesión: '+new Date(Math.min(...ss.map(s=>s.start))).toLocaleDateString('es-ES')+' · Última: '+new Date(Math.max(...ss.map(s=>s.end))).toLocaleDateString('es-ES')));target.append(card);}}
function renderReports(){const ss=C.mine(state).filter(s=>inPeriod(s,$('reportPeriod').value)),total=ss.reduce((n,s)=>n+C.seconds(s),0);$('reports').replaceChildren(el('h1',C.format(total)));for(const p of state.projects){const time=ss.filter(s=>s.projectId===p.id).reduce((n,s)=>n+C.seconds(s),0);if(!time)continue;const card=el('article',null,'projectcard'),bar=el('div',null,'bar'),fill=el('span');fill.style.width=(total?time/total*100:0)+'%';bar.append(fill);card.append(el('strong',p.name+' · '+C.format(time)),bar);$('reports').append(card);}if(!total)$('reports').append(el('p','No hay tiempo registrado en este periodo.','empty'));}
function toggle(){if(manualMode){const session={id:C.id(),userId:state.userId,projectId:$('project').value,description:$('description').value.trim(),workType:$('workType').value,units:Number($('units').value),start:new Date($('manualStart').value).getTime(),end:new Date($('manualEnd').value).getTime()};if(mutate(n=>C.upsert(n,session)))notify('Sesión manual guardada.');return;}mutate(n=>{if(n.active)C.stop(n);else C.start(n,{projectId:$('project').value,description:$('description').value.trim(),workType:$('workType').value,units:Number($('units').value)});});}
$('timerForm').onsubmit=e=>{e.preventDefault();toggle();};$('miniToggle').onclick=()=>{if(state.active)mutate(n=>C.stop(n));else {setManualMode(false);toggle();}};
$('miniButton').onclick=()=>{$('mini').hidden=!$('mini').hidden;$('miniButton').setAttribute('aria-expanded',String(!$('mini').hidden));};document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='d'&&!e.altKey){e.preventDefault();if(!$('editor').open&&!$('projectEditor').open)setManualMode(!manualMode);return;}if(e.key==='Escape'){$('mini').hidden=true;$('miniButton').setAttribute('aria-expanded','false');}if((e.ctrlKey||e.metaKey)&&e.key==='Enter'&&!$('editor').open&&!$('projectEditor').open){e.preventDefault();toggle();}});
const headings={timer:'Un momento para enfocarte.',day:'Tu día, hora a hora.',projects:'De la idea al hecho.',reports:'Así has invertido tu tiempo.',settings:'Tu espacio, a tu manera.'};
function showView(view){const b=document.querySelector('[data-view="'+view+'"]');for(const v of Object.keys(headings))$(v+'View').hidden=v!==b.dataset.view;document.querySelectorAll('[data-view]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',String(x===b));x.setAttribute('aria-current',x===b?'page':'false');});$('heading').textContent=headings[view];$('trackingHeader').hidden=!['timer','day'].includes(view);$('moreNav').hidden=true;$('moreButton').setAttribute('aria-expanded','false');if(view==='day')requestAnimationFrame(()=>$('timelineScroll').scrollTop=Math.max(0,(new Date().getHours()-2)*60));}
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>showView(b.dataset.view));
$('moreButton').onclick=()=>{$('moreNav').hidden=!$('moreNav').hidden;$('moreButton').setAttribute('aria-expanded',String(!$('moreNav').hidden));};
$('user').onchange=()=>mutate(n=>{if(n.active)throw Error('Detén la sesión para cambiar de perfil.');n.userId=$('user').value;});for(const id of ['search','period'])$(id).addEventListener('input',renderSessions);$('reportPeriod').onchange=renderReports;
function localDate(t){const d=new Date(t);return new Date(t-d.getTimezoneOffset()*60000).toISOString().slice(0,19);}
function openEditor(s){if(s){try{C.own(state,s);}catch(e){notify(e.message);return;}}editing=s?.id||null;$('editTitle').textContent=s?'Editar sesión':'Añadir sesión';options($('editProject'),state.projects.filter(p=>!p.archived||p.id===s?.projectId),s?.projectId||$('project').value);$('editDescription').value=s?.description||'';$('editStart').value=localDate(s?.start||Date.now()-1800000);$('editEnd').value=localDate(s?.end||Date.now());$('editType').value=s?.workType||'Visuales';$('editUnits').value=s?.units||0;$('editError').textContent='';$('deleteEdit').hidden=!s;updateEditDuration();$('editor').showModal();}
$('manual').onclick=()=>openEditor();$('cancelEdit').onclick=()=>$('editor').close();$('editForm').onsubmit=e=>{e.preventDefault();const existing=state.sessions.find(s=>s.id===editing);const session={id:editing||C.id(),userId:existing?.userId||state.userId,projectId:$('editProject').value,description:$('editDescription').value.trim(),start:new Date($('editStart').value).getTime(),end:new Date($('editEnd').value).getTime(),workType:$('editType').value,units:Number($('editUnits').value)};try{C.validate(session,state);}catch(error){$('editError').textContent=error.message;return;}if(mutate(n=>C.upsert(n,session))){$('editor').close();notify('Sesión guardada.');}};
$('newProject').onclick=()=>$('projectEditor').showModal();$('cancelProject').onclick=()=>$('projectEditor').close();$('projectForm').onsubmit=e=>{e.preventDefault();if(mutate(n=>{const name=$('projectName').value.trim(),client=$('clientName').value.trim();if(!name||!client)throw Error('Escribe el nombre y el cliente.');if(n.projects.some(p=>p.name.toLowerCase()===name.toLowerCase()&&p.client.toLowerCase()===client.toLowerCase()))throw Error('Ya existe ese proyecto para el cliente.');n.projects.push({id:C.id(),name,client,historicalMinutes:Number($('historical').value),archived:false});})){$('projectEditor').close();$('projectForm').reset();}};
$('profileForm').onsubmit=e=>{e.preventDefault();if(mutate(n=>{if(n.active)throw Error('Detén el temporizador antes de cambiar de perfil.');const name=$('profileName').value.trim();if(!name)throw Error('Escribe un nombre.');if(n.users.some(u=>u.name.toLowerCase()===name.toLowerCase()))throw Error('Ese perfil ya existe.');const id=C.id();n.users.push({id,name});n.userId=id;}))$('profileForm').reset();};
for(const id of ['palette','theme'])$(id).onchange=()=>mutate(n=>{n[id]=$(id).value;});
function download(name,text,type){const url=URL.createObjectURL(new Blob([text],{type})),a=el('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
$('backup').onclick=()=>download('task-track-backup.json',JSON.stringify(C.personalBackup(state),null,2),'application/json');
$('export').onclick=()=>download('task-track-sesiones.csv',C.csv([['ID','Proyecto','Actividad','Perfil','Inicio','Fin','Segundos','Tipo','Unidades'],...filtered().map(s=>[s.id,projectName(s.projectId),s.description,userName(s.userId),new Date(s.start).toISOString(),new Date(s.end).toISOString(),C.seconds(s),s.workType,s.units])]),'text/csv;charset=utf-8');
window.addEventListener('storage',e=>{if(e.key===KEY){notify('Los datos han cambiado en otra ventana. Recarga para continuar.');readOnly=true;$('toggle').disabled=true;$('saveState').textContent='Recarga necesaria';}});
if(!localStorage.getItem(KEY)&&!readOnly){try{localStorage.setItem(KEY,JSON.stringify(state));}catch{readOnly=true;notify('El navegador no permite guardar datos.');}}
function dayBounds(){const [y,m,d]=$('dayDate').value.split('-').map(Number);const start=new Date(y,m-1,d),end=new Date(y,m-1,d+1);return [start.getTime(),end.getTime()];}
function renderDay(){if(!$('dayDate').value)return;const [start,end]=dayBounds();const records=C.daily(state,start,end);$('dayTotal').textContent=C.format(records.reduce((n,s)=>n+C.dayOverlap(s,start,end)/1000,0));$('daySessions').replaceChildren();for(const s of records){const row=el('article',null,'session');row.append(el('div',new Date(Math.max(s.start,start)).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})+' – '+new Date(Math.min(s.end,end)).toLocaleTimeString('es-ES',{hour:'2-digit',minute:'2-digit'})),el('div',(s.description||'Sin descripción')+' · '+projectName(s.projectId),'details'),el('time',C.format(C.dayOverlap(s,start,end)/1000)),action('Editar',()=>openEditor(s)));$('daySessions').append(row);}
const timeline=$('timeline');timeline.replaceChildren();for(let h=0;h<24;h++){const cell=el('div',String(h).padStart(2,'0')+':00','hour');cell.style.top=(h/24*100)+'%';timeline.append(cell);}for(const s of records){const b=action((s.description||'Sin descripción')+' · '+C.format(C.dayOverlap(s,start,end)/1000),()=>openEditor(s));b.className='timeblock';b.style.borderLeftColor=projectColor(s.projectId);b.style.top=((Math.max(s.start,start)-start)/(end-start)*100)+'%';b.style.height=Math.max(2,(Math.min(s.end,end)-Math.max(s.start,start))/(end-start)*100)+'%';timeline.append(b);}if(start<=Date.now()&&Date.now()<end){const line=el('div',null,'nowline');line.style.top=((Date.now()-start)/(end-start)*100)+'%';timeline.append(line);}if(!records)$('daySessions').append(el('p','No hay sesiones para este día y perfil.','empty'));const first=records[0];const target=first?Math.max(0,Math.min(1260,Math.floor((Math.max(first.start,start)-start)/60000)-90)):Math.max(0,(new Date().getHours()-2)*60);requestAnimationFrame(()=>$('timelineScroll').scrollTop=target); }
function setDay(date){$('dayDate').value=localDate(date.getTime()).slice(0,10);renderDay();}
$('dayDate').onchange=renderDay;$('previousDay').onclick=()=>{const [s]=dayBounds();const d=new Date(s);d.setDate(d.getDate()-1);setDay(d);};$('nextDay').onclick=()=>{const [s]=dayBounds();const d=new Date(s);d.setDate(d.getDate()+1);setDay(d);};$('today').onclick=()=>setDay(new Date());setDay(new Date());
function setManualMode(value){manualMode=value;$('manualMode').checked=value;$('manualFields').hidden=!value;for(const id of ['manualStart','manualEnd'])$(id).required=value;if(value&&!$('manualStart').value){$('manualStart').value=localDate(Date.now()-1800000);$('manualEnd').value=localDate(Date.now());}render();}
$('manualMode').onchange=()=>setManualMode($('manualMode').checked);
function updateEditDuration(){$('editDuration').value=C.format((new Date($('editEnd').value)-new Date($('editStart').value))/1000);}
$('editStart').onchange=updateEditDuration;$('editEnd').onchange=updateEditDuration;
$('editDuration').onchange=()=>{const m=$('editDuration').value.match(/^(\d+):([0-5]\d):([0-5]\d)$/);if(m)$('editEnd').value=localDate(new Date($('editStart').value).getTime()+(Number(m[1])*3600+Number(m[2])*60+Number(m[3]))*1000);};
$('deleteEdit').onclick=()=>{if(editing&&mutate(n=>C.remove(n,editing))){$('editor').close();notify('Sesión eliminada.');}};
render();setInterval(tick,500);
